import SwiftUI

// 自定义一个简单的卡片视图，它的内容由 @ViewBuilder 闭包提供
struct CardView<Content: View>: View {
    // 使用 @ViewBuilder 属性包装器标记 content 参数
    // 这意味着调用 CardView 时，花括号内的所有视图都会被自动组合成一个 Content 类型
    let content: @ViewBuilder () -> Content

    var body: some View {
        VStack {
            // 直接使用 content() 调用这个闭包，它返回的视图将在这里显示
            content()
        }
        .padding()
        .background(Color.gray.opacity(0.1))
        .cornerRadius(10)
    }
}

// 使用 CardView
struct ContentView: View {
    @State private var showDetails = true

    var body: some View {
        VStack(spacing: 20) {
            // 使用我们的自定义 CardView
            CardView {
                // 这里是 @ViewBuilder 的作用域
                Text("主标题")
                    .font(.headline)

                // 使用 @ViewBuilder 支持的控制流：if
                if showDetails {
                    Text("这里是详细描述信息，当 showDetails 为 true 时显示。")
                        .font(.caption)
                }

                // 使用 @ViewBuilder 支持的控制流：switch (模拟不同状态)
                let status = "active"
                switch status {
                case "active":
                    HStack {
                        Image(systemName: "checkmark.circle.fill")
                            .foregroundColor(.green)
                        Text("状态：活跃")
                    }
                default:
                    Text("状态：未知")
                }
            }

            // 另一个卡片，展示 @ViewBuilder 如何处理不同内容
            CardView {
                Image(systemName: "star.fill")
                    .foregroundColor(.yellow)
                    .font(.largeTitle)
                Text("收藏")
            }

            Button("切换详情") {
                showDetails.toggle()
            }
        }
        .padding()
    }
}

